int s = socket(AF_INET, SOCK_STREAM, 0);
struct sockaddr_in a = {0};
a.sin_family = AF_INET;
a.sin_port = htons(7000);
a.sin_addr.s_addr = htonl(INADDR_ANY);
bind(s, (struct sockaddr *)&a, sizeof a);
listen(s, 5);
for (;;) {                      /* iterative TCP echo server */
    int c = accept(s, NULL, NULL);
    char buf[512];
    ssize_t n;
    while ((n = recv(c, buf, sizeof buf, 0)) > 0)
        send(c, buf, n, 0);
    close(c);
}

int s = socket(AF_INET, SOCK_STREAM, 0);   /* TCP echo client */
struct sockaddr_in srv = {0};
srv.sin_family = AF_INET;
srv.sin_port = htons(7000);
inet_pton(AF_INET, "127.0.0.1", &srv.sin_addr);
connect(s, (struct sockaddr *)&srv, sizeof srv);
send(s, "hello", 5, 0);
char buf[512];
ssize_t n = recv(s, buf, sizeof buf - 1, 0);
buf[n > 0 ? n : 0] = '\0';
printf("echo: %s\n", buf);
close(s);

signal(SIGCHLD, SIG_IGN);           /* children are reaped automatically */
for (;;) {
    int c = accept(s, NULL, NULL);
    if (c < 0) continue;
    if (fork() == 0) {              /* child */
        close(s);                   /* the child never accepts */
        serve(c);                   /* recv/send loop for this client */
        close(c);
        _exit(0);
    }
    close(c);                       /* parent keeps only the listening socket */
}

